// ==============================================================================
// Week 5 Capstone: 입력 가드레일 & 다형성 입력 정규화 (Input Guardrail & Normalizer)
// ==============================================================================
const input = $input.first().json;

// 1. 다형성 입력 필드 파싱 (prompt, raw_message, query, incident_summary 대응)
const rawText = input.body?.prompt || 
                input.body?.raw_message || 
                input.body?.query || 
                input.body?.incident_summary || 
                input.prompt || 
                input.raw_message || 
                input.query || 
                (typeof input.body === 'string' ? input.body : "");

const requester = input.body?.requester || input.requester || "automated-system-monitor";

// 2. 프롬프트 인젝션 및 시스템 파괴 명령 정규식 검사
const injectionPatterns = [
  /ignore\s+(all\s+)?previous\s+instructions/i,
  /system\s+override/i,
  /drop\s+table/i,
  /delete\s+from/i,
  /rm\s+-rf/i,
  /chmod\s+777/i,
  /<script>/i,
  /grant\s+admin\s+access/i,
  /export\s+all\s+secrets/i
];

let isThreatDetected = false;
let threatReason = "";

for (const pattern of injectionPatterns) {
  if (pattern.test(rawText)) {
    isThreatDetected = true;
    threatReason = `악성 인젝션 패턴 감지: ${pattern.toString()}`;
    break;
  }
}

// 3. 비정형 텍스트로부터 고객사명 및 서버 ID 정규화 추출
let companyName = input.body?.company_name || input.company_name || "";
if (!companyName) {
  if (rawText.includes("대한전자")) companyName = "(주)대한전자";
  else if (rawText.includes("미래파이낸셜")) companyName = "(주)미래파이낸셜";
  else if (rawText.includes("성우모빌리티")) companyName = "성우모빌리티시스템";
  else if (rawText.includes("에듀포커스")) companyName = "에듀포커스인터내셔널";
  else if (rawText.includes("넥서스로지스틱스")) companyName = "넥서스로지스틱스(주)";
  else if (rawText.includes("한빛바이오랩")) companyName = "한빛바이오랩";
  else if (rawText.includes("알파소프트웨어")) companyName = "알파소프트웨어솔루션";
  else if (rawText.includes("글로벌커머스")) companyName = "글로벌커머스네트워크";
  else if (rawText.includes("핀테크허브")) companyName = "핀테크허브글로벌";
  else if (rawText.includes("메디컬인포")) companyName = "메디컬인포케어";
  else companyName = "미등록 고객사";
}

let targetServer = input.body?.server_id || input.server_id || "";
if (!targetServer) {
  if (rawText.includes("app-was-01")) targetServer = "app-was-01";
  else if (rawText.includes("auth-api-01")) targetServer = "auth-api-01";
  else targetServer = "db-primary-01";
}

return [{
  json: {
    is_safe: !isThreatDetected,
    threat_reason: threatReason,
    clean_prompt: rawText.trim(),
    company_name: companyName,
    server_id: targetServer,
    requester: requester,
    received_at: new Date().toISOString()
  }
}];

