// ==============================================================================
// Week 5: 고객사 프로파일 결합 및 인시던트 티켓 속성(Severity/Category) 합성
// ==============================================================================
const guardrailItem = $('Input Guardrail & Intake Normalizer').item.json;
const customerRows = $input.all();

let customerId = "CUST-1099";
let companyName = guardrailItem.company_name || "미등록 고객사";
let contractTier = "Standard";
let slaMinutes = 240;
let amEmail = "helpdesk@enterprise.internal";

if (customerRows.length > 0 && customerRows[0].json?.customer_id) {
  const row = customerRows[0].json;
  customerId = row.customer_id;
  companyName = row.company_name;
  contractTier = row.contract_tier;
  slaMinutes = row.sla_response_minutes;
  amEmail = row.account_manager_email;
}

// 텍스트 기반 장애 심각도 및 카테고리 판정
const text = guardrailItem.clean_prompt.toLowerCase();
let severity = "Low";
let category = "Inquiry";

if (text.includes("커넥션") || text.includes("500") || text.includes("고갈") || text.includes("db")) {
  category = "Database";
  severity = (contractTier === 'VIP') ? 'Critical' : 'High';
} else if (text.includes("메모리") || text.includes("full gc") || text.includes("힙") || text.includes("was")) {
  category = "Application";
  severity = "High";
} else if (text.includes("세션") || text.includes("로그인") || text.includes("만료")) {
  category = "Account/Auth";
  severity = "Low";
}

const ticketId = `TKT-2026-CAP-${Math.floor(1000 + Math.random() * 9000)}`;

return [{
  json: {
    ticket_id: ticketId,
    customer_id: customerId,
    company_name: companyName,
    contract_tier: contractTier,
    sla_response_minutes: slaMinutes,
    account_manager_email: amEmail,
    severity: severity,
    category: category,
    summary: guardrailItem.clean_prompt,
    server_id: guardrailItem.server_id,
    requester: guardrailItem.requester,
    created_at: new Date().toISOString()
  }
}];

