const input = $input.first().json;

const ticketId = input.body?.ticket_id || input.query?.ticket_id || input.ticket_id || "TKT-UNKNOWN";
const decision = String(input.body?.decision || input.query?.decision || input.decision || "approve").toLowerCase().trim();
const authorizedBy = input.body?.authorized_by || input.authorized_by || "sre_oncall_engineer@enterprise.internal";
const serverId = input.body?.server_id || input.server_id || "db-primary-01";
const reason = input.body?.reason || input.reason || "긴급 장애 완화 승인";

return [{
  json: {
    ticket_id: ticketId,
    decision: decision,
    is_approved: (decision === 'approve' || decision === 'approved' || decision === 'true'),
    authorized_by: authorizedBy,
    server_id: serverId,
    reason: reason,
    decided_at: new Date().toISOString()
  }
}];

